import React, { useEffect, useMemo, useRef, useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import MISplitScreen from "./MISplitScreen.jsx";
import MILeftPanel from "./MILeftPanel.jsx";
import MIRightPanel from "./MIRightPanel.jsx";

/**
 * InterviewRoom
 * - Loads immediately into a 50/50 split screen.
 * - Center divider activates on hover; drag to resize (30%–70%) via MISplitScreen.
 * - Starts mic/camera capture on mount, previews into #ir-preview (left panel).
 * - Simple record/stop lifecycle with a running timer.
 */
export default function InterviewRoom() {
  const nav = useNavigate();
  const { state } = useLocation();
  const selectedMode =
    state?.mode || localStorage.getItem("recording.mode") || "video_audio"; // "audio_only" | "video_audio"

  const [error, setError] = useState("");
  const [status, setStatus] = useState("requesting"); // requesting | recording | stopped
  const [duration, setDuration] = useState(0);

  // Media
  const streamRef = useRef(null);
  const mediaRecRef = useRef(null);
  const chunksRef = useRef([]);
  const startedAtRef = useRef(0);
  const tickRef = useRef(null);

  const isSecure =
    typeof window !== "undefined"
      ? window.isSecureContext || window.location.hostname === "localhost"
      : false;

  const constraints = useMemo(
    () =>
      selectedMode === "audio_only"
        ? { audio: { echoCancellation: true, noiseSuppression: true }, video: false }
        : {
            audio: { echoCancellation: true, noiseSuppression: true },
            video: { width: { ideal: 1280 }, height: { ideal: 720 } },
          },
    [selectedMode]
  );

  useEffect(() => {
    (async () => {
      if (!isSecure) {
        setError("Capture requires HTTPS or localhost.");
        setStatus("stopped");
        return;
      }
      try {
        const stream = await navigator.mediaDevices.getUserMedia(constraints);
        streamRef.current = stream;

        const v = document.getElementById("ir-preview");
        if (v && constraints.video) {
          v.srcObject = stream;
          v.muted = true;
          v.play().catch(() => {});
        }

        const mime =
          selectedMode === "audio_only"
            ? "audio/webm;codecs=opus"
            : (MediaRecorder.isTypeSupported("video/webm;codecs=vp9,opus")
                ? "video/webm;codecs=vp9,opus"
                : "video/webm;codecs=vp8,opus");

        const mr = new MediaRecorder(stream, {
          mimeType: mime,
          audioBitsPerSecond: 128000,
          videoBitsPerSecond: 2500000,
        });
        mediaRecRef.current = mr;
        chunksRef.current = [];

        mr.ondataavailable = (e) => {
          if (e.data && e.data.size > 0) chunksRef.current.push(e.data);
        };
        mr.onstop = () => {
          try {
            // You can persist/upload chunksRef.current if needed.
          } catch (e) {
            console.warn("Finalize error:", e);
          } finally {
            setStatus("stopped");
          }
        };

        mr.start(1000); // collect data every second
        startedAtRef.current = Date.now();
        setStatus("recording");
        tickRef.current = setInterval(() => {
          setDuration(Math.max(0, Math.floor((Date.now() - startedAtRef.current) / 1000)));
        }, 1000);
      } catch (err) {
        console.error(err);
        setError(
          err?.name === "NotAllowedError"
            ? "Permission was denied. Allow mic/camera and reload."
            : "Could not start capture. Check device and site permissions."
        );
        setStatus("stopped");
      }
    })();

    return () => {
      if (tickRef.current) clearInterval(tickRef.current);
      try {
        if (mediaRecRef.current && mediaRecRef.current.state !== "inactive") {
          mediaRecRef.current.stop();
        }
      } catch {}
      try {
        streamRef.current?.getTracks()?.forEach((t) => t.stop());
      } catch {}
    };
  }, [constraints, isSecure, selectedMode]);

  const stopNow = () => {
    try {
      if (mediaRecRef.current && mediaRecRef.current.state !== "inactive") {
        mediaRecRef.current.stop();
      }
      if (tickRef.current) {
        clearInterval(tickRef.current);
        tickRef.current = null;
      }
    } catch {}
  };

  const mins = String(Math.floor(duration / 60)).padStart(2, "0");
  const secs = String(duration % 60).padStart(2, "0");

  return (
    <div className="min-h-screen p-4">
      <h2 className="text-xl font-semibold mb-2">Interview Room</h2>
      <div className="text-sm text-white/70 mb-4">
        Mode: <b>{selectedMode === "audio_only" ? "Audio-only" : "Video + Audio"}</b>
      </div>

      {/* Split screen appears immediately on page load */}
      <MISplitScreen
        initial={50}
        min={30}
        max={70}
        height="72vh"
        left={<MILeftPanel />}
        right={
          <MIRightPanel>
            <div className="text-white/80 space-y-3">
              {status === "requesting" && (
                <div>Requesting microphone/camera permission…</div>
              )}

              {status === "recording" && (
                <div className="flex items-center gap-3">
                  <span className="inline-flex items-center gap-2 text-green-300">
                    <span className="w-2.5 h-2.5 rounded-full bg-green-400 animate-pulse" />
                    Recording… {mins}:{secs}
                  </span>
                  <button
                    onClick={stopNow}
                    className="px-3 py-1.5 rounded-md bg-white/10 border border-white/15 hover:bg-white/20"
                  >
                    Stop &amp; Save
                  </button>
                </div>
              )}

              {status === "stopped" && (
                <div className="rounded-md border border-white/15 bg-white/5 p-3">
                  <div className="text-white/80 mb-1">
                    Recording stopped. You can navigate away safely.
                  </div>
                  <div className="mt-3">
                    <button
                      onClick={() => nav("/")}
                      className="px-3 py-1.5 rounded-md bg-green-400 text-gray-900 font-semibold hover:bg-green-300"
                    >
                      Back to Home
                    </button>
                  </div>
                </div>
              )}

              {error && <div className="text-red-300">{error}</div>}

              <div className="text-white/60 text-sm pt-1">
                Tip: Resize the panels by grabbing the center line (each side can grow up to 70%).
              </div>
            </div>
          </MIRightPanel>
        }
      />
    </div>
  );
}
