import React from "react";

export default function MIRightPanel({ children }) {
  return (
    <div className="h-full w-full p-4">
      <div className="h-full rounded-lg border border-white/10 bg-white/5 p-4">
        {children ?? (
          <div className="text-white/80">
            <h3 className="text-lg font-semibold mb-2">Instructions</h3>
            <ul className="list-disc list-inside space-y-1 text-sm">
              <li>Follow the prompts from the Interview Avatar.</li>
              <li>Keep your camera at eye level and speak clearly.</li>
              <li>Use the divider to resize panels (min 30%, max 70%).</li>
            </ul>
          </div>
        )}
      </div>
    </div>
  );
}
