import React, { useEffect, useRef, useState } from "react";

/**
 * Split screen with draggable vertical handle.
 * - Starts 50/50.
 * - On hover, the center line activates with col-resize cursor.
 * - Dragging clamps so left ∈ [30%, 70%] (so either side can grow to 70%).
 *
 * Props:
 *  - left: ReactNode (left panel content)
 *  - right: ReactNode (right panel content)
 *  - initial (number, default 50): starting left width in %
 *  - min (number, default 30): minimum left width in %
 *  - max (number, default 70): maximum left width in %
 *  - height (string, default '70vh'): container height
 */
export default function MISplitScreen({
  left,
  right,
  initial = 50,
  min = 30,
  max = 70,
  height = "70vh",
}) {
  const containerRef = useRef(null);
  const [leftPct, setLeftPct] = useState(
    Math.max(min, Math.min(max, initial))
  );
  const [dragging, setDragging] = useState(false);
  const [hovering, setHovering] = useState(false);

  // Attach global listeners during drag
  useEffect(() => {
    function onMove(e) {
      if (!dragging || !containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      const clientX = e.clientX ?? (e.touches && e.touches[0]?.clientX);
      if (typeof clientX !== "number") return;
      const pct = ((clientX - rect.left) / rect.width) * 100;
      setLeftPct(Math.max(min, Math.min(max, pct)));
    }

    function onUp() {
      if (!dragging) return;
      setDragging(false);
      document.body.style.userSelect = "";
      document.body.style.cursor = "";
    }

    if (dragging) {
      window.addEventListener("pointermove", onMove, { passive: false });
      window.addEventListener("pointerup", onUp, { passive: false });
      window.addEventListener("touchmove", onMove, { passive: false });
      window.addEventListener("touchend", onUp, { passive: false });
      document.body.style.userSelect = "none";
      document.body.style.cursor = "col-resize";
    }
    return () => {
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);
      window.removeEventListener("touchmove", onMove);
      window.removeEventListener("touchend", onUp);
    };
  }, [dragging, min, max]);

  const handlePointerDown = (e) => {
    e.preventDefault();
    setDragging(true);
  };

  const lineLeft = `${leftPct}%`;

  return (
    <div
      ref={containerRef}
      className="relative w-full rounded-lg border border-white/10 bg-white/5 overflow-hidden"
      style={{ height }}
    >
      {/* Left panel */}
      <div
        className="absolute inset-y-0 left-0 overflow-auto"
        style={{ width: `${leftPct}%` }}
      >
        <div className="h-full w-full">{left}</div>
      </div>

      {/* Right panel */}
      <div
        className="absolute inset-y-0 right-0 overflow-auto"
        style={{ width: `${100 - leftPct}%` }}
      >
        <div className="h-full w-full">{right}</div>
      </div>

      {/* Center handle (visible line + larger hit area) */}
      <div
        className="absolute inset-y-0"
        style={{ left: lineLeft, transform: "translateX(-50%)" }}
        onMouseEnter={() => setHovering(true)}
        onMouseLeave={() => setHovering(false)}
      >
        {/* Hit area for easy grabbing */}
        <div
          onPointerDown={handlePointerDown}
          onTouchStart={handlePointerDown}
          role="separator"
          aria-orientation="vertical"
          aria-label="Resize panels"
          className="h-full"
          style={{ width: 16, marginLeft: -8, cursor: "col-resize" }}
        >
          {/* The visible 2px line */}
          <div
            className={`h-full mx-auto`}
            style={{
              width: 2,
              background: dragging
                ? "rgba(96, 165, 250, 1)" // sky-400
                : hovering
                ? "rgba(255,255,255,0.9)"
                : "rgba(255,255,255,0.35)",
              boxShadow: hovering || dragging ? "0 0 0 2px rgba(96,165,250,0.35)" : "none",
            }}
          />
        </div>
      </div>

      {/* Optional dashed guide to make the split feel obvious on load */}
      <div
        className="pointer-events-none absolute inset-y-0"
        style={{ left: lineLeft, transform: "translateX(-50%)" }}
      >
        <div
          className="h-full"
          style={{
            width: 2,
            borderLeft: "1px dashed rgba(255,255,255,0.25)",
          }}
        />
      </div>
    </div>
  );
}
